set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';const root='/var/lib/news-flow/stability-20261123',require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),rows=db.prepare("SELECT * FROM import_receipts WHERE status='created' ORDER BY imported_at DESC LIMIT 25").all(),r={at:new Date().toISOString(),rows:[]};try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;if(!proof.verified||!info.version.number.startsWith('5.6.')||createHash('sha256').update(info.cluster_uuid).digest('hex')!==proof.clusterFingerprint)throw Error('QC_ES_IDENTITY_CHANGED');r.esHealth=await es.cluster.health({timeout:'5s'});const result=await es.mget({body:{docs:rows.map(row=>({_index:row.es_index,_type:row.es_type,_id:row.es_id}))}});for(let i=0;i<rows.length;i++){const row=rows[i],hit=result.docs[i],s=hit._source,event=db.prepare("SELECT details FROM events WHERE kind='verified' AND url=? ORDER BY id DESC LIMIT 1").get(row.url),metric=event&&JSON.parse(event.details);r.rows.push({id:row.id,url:row.url,found:hit.found===true,urlMatches:s?.url===row.url,originalDateMatches:!!metric&&metric.publishedDate===s?.publishedDate,titlePresent:!!s?.title,contentPresent:!!s?.content,importedAt:row.imported_at});}r.verified=r.rows.length===25&&r.rows.every(s=>s.found&&s.urlMatches&&s.originalDateMatches&&s.titlePresent&&s.contentPresent);fs.writeFileSync(root+'/news-es-readback.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));}finally{db.close();es.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/stability-20261123/news-es-readback.json "$upload_dir/.qc-stability-news-es-readback.json"
